    21	        Some(
    22	            "company"
    23	            | "charity"
    24	            | "trade union"
    25	            | "union"
    26	            | "other organisation"
    27	            | "organisation"
    28	            | "unincorporated association"
    29	            | "registered party"
    30	            | "trust"
    31	            | "limited liability partnership"
    32	            | "friendly society"
    33	            | "building society",
    34	        ) => EntityKind::Organisation,
