   146	impl Components {
   147	    fn new(input: &ResolutionInput) -> Self {
   148	        let mut components: Vec<BTreeSet<FunderObservationId>> = Vec::new();
   149	        let mut anchors = BTreeMap::<String, usize>::new();
   150	        let mut group = BTreeMap::new();
   151	        for observation in input.observations.values() {
   152	            let index = if let Some(number) = company(observation) {
   153	                *anchors.entry(number).or_insert_with(|| {
   154	                    components.push(BTreeSet::new());
   155	                    components.len() - 1
   156	                })
   157	            } else {
   158	                components.push(BTreeSet::new());
   159	                components.len() - 1
   160	            };
   161	            components[index].insert(observation.funder_id.clone());
   162	            group.insert(observation.funder_id.clone(), index);
   163	        }
   164	        Self {
   165	            members: components,
   166	            group,
   167	        }
   168	    }
   169	    fn apply(&mut self, input: &ResolutionInput, edges: &mut CandidateEdges) {
   170	        let mut unanchored = Self::new(input);
   171	        for edge in edges
   172	            .values()
   173	            .filter(|edge| matches!(edge.eligibility, EdgeEligibility::Link(_)))
   174	        {
   175	            let edge = &edge.decision;
   176	            if company(&input.observations[&edge.left_funder_id]).is_none()
   177	                && company(&input.observations[&edge.right_funder_id]).is_none()
   178	            {
   179	                unanchored.join(&edge.left_funder_id, &edge.right_funder_id);
   180	            }
   181	        }
   182	        let mut candidate_companies = BTreeMap::<usize, BTreeSet<String>>::new();
   183	        for candidate in edges
   184	            .values()
   185	            .filter(|edge| matches!(edge.eligibility, EdgeEligibility::Link(_)))
   186	        {
   187	            let edge = &candidate.decision;
   188	            for (unknown, known) in [
   189	                (&edge.left_funder_id, &edge.right_funder_id),
   190	                (&edge.right_funder_id, &edge.left_funder_id),
   191	            ] {
   192	                if company(&input.observations[unknown]).is_none()
   193	                    && let Some(number) = company(&input.observations[known])
   194	                {
   195	                    candidate_companies
   196	                        .entry(unanchored.group[unknown])
   197	                        .or_default()
   198	                        .insert(number);
   199	                }
   200	            }
   201	        }
   202	        for candidate in edges.values_mut() {
   203	            let edge = &mut candidate.decision;
   204	            let evidence = match candidate.eligibility {
   205	                EdgeEligibility::Reject(reason) => {
   206	                    edge.disposition = PairDisposition::Rejected;
   207	                    edge.reason = reason;
   208	                    continue;
   209	                }
   210	                EdgeEligibility::Review => continue,
   211	                EdgeEligibility::Link(evidence) => evidence,
   212	            };
   213	            let ambiguous_attachment = [
   214	                (&edge.left_funder_id, &edge.right_funder_id),
   215	                (&edge.right_funder_id, &edge.left_funder_id),
   216	            ]
   217	            .iter()
   218	            .any(|(unknown, known)| {
   219	                company(&input.observations[*unknown]).is_none()
   220	                    && company(&input.observations[*known]).is_some()
   221	                    && candidate_companies
   222	                        .get(&unanchored.group[*unknown])
   223	                        .is_some_and(|numbers| numbers.len() > 1)
   224	            });
   225	            if ambiguous_attachment {
   226	                edge.reason = PairReason::CompetingCompanyAnchors;
   227	                continue;
   228	            }
   229	            let left = self.group[&edge.left_funder_id];
   230	            let right = self.group[&edge.right_funder_id];
   231	            let ids = self.members[left]
   232	                .union(&self.members[right])
   233	                .cloned()
   234	                .collect::<BTreeSet<_>>();
   235	            let companies = ids
   236	                .iter()
   237	                .filter_map(|id| company(&input.observations[id]))
   238	                .collect::<BTreeSet<_>>();
   239	            let kinds = ids
   240	                .iter()
   241	                .map(|id| kind(&input.observations[id]))
   242	                .collect::<Vec<_>>();
   243	            if companies.len() > 1
   244	                || (kinds.contains(&EntityKind::Person)
   245	                    && kinds.contains(&EntityKind::Organisation))
   246	            {
   247	                edge.disposition = PairDisposition::Rejected;
   248	                edge.reason = PairReason::ComponentIdentityConflict;
   249	                continue;
   250	            }
   251	            self.join(&edge.left_funder_id, &edge.right_funder_id);
   252	            edge.disposition = PairDisposition::Accepted;
   253	            edge.reason = match evidence {
   254	                LinkEvidence::Statistical => PairReason::ExactNameFullAddressThreshold,
   255	                LinkEvidence::DonorName => PairReason::ExactDonorName,
   256	            };
   257	        }
   258	    }
   259	    fn join(&mut self, left_id: &FunderObservationId, right_id: &FunderObservationId) {
   260	        let left = self.group[left_id];
   261	        let right = self.group[right_id];
   262	        if left != right {
   263	            let members = std::mem::take(&mut self.members[right]);
   264	            for id in &members {
   265	                self.group.insert(id.clone(), left);
   266	            }
   267	            self.members[left].extend(members);
   268	        }
   269	    }
   270	    fn outcomes(
   271	        &self,
   272	        input: &ResolutionInput,
   273	        edges: &CandidateEdges,
   274	        run_key: &str,
   275	    ) -> Vec<ObservationResolution> {
   276	        let mut statistical = Self::new(input);
   277	        let mut statistical_groups = BTreeSet::new();
   278	        for candidate in edges.values() {
   279	            if candidate.decision.disposition == PairDisposition::Accepted
   280	                && matches!(
   281	                    candidate.eligibility,
   282	                    EdgeEligibility::Link(LinkEvidence::Statistical)
   283	                )
   284	            {
   285	                let edge = &candidate.decision;
   286	                statistical.join(&edge.left_funder_id, &edge.right_funder_id);
   287	                statistical_groups.insert(self.group[&edge.left_funder_id]);
   288	            }
   289	        }
   290	        let mut observations = Vec::new();
   291	        for observation in input.observations.values() {
   292	            let ids = &self.members[self.group[&observation.funder_id]];
   293	            let statistical_connected = ids
   294	                .iter()
   295	                .map(|id| statistical.group[id])
   296	                .collect::<BTreeSet<_>>()
   297	                .len()
   298	                == 1;
   299	            let component_basis = if statistical_connected {
   300	                IdentityBasis::StatisticalLink
   301	            } else if statistical_groups.contains(&self.group[&observation.funder_id]) {
   302	                IdentityBasis::StatisticalAndDonorNameLink
   303	            } else {
   304	                IdentityBasis::DonorNameLink
   305	            };
   306	            let number = ids.iter().find_map(|id| company(&input.observations[id]));
   307	            let (identity_id, identity_basis) = number.map_or_else(
   308	                || {
   309	                    if observation.name_normalized.is_none() {
   310	                        (None, IdentityBasis::Unresolved)
   311	                    } else {
   312	                        let leader = ids
   313	                            .first()
   314	                            .expect("each observation belongs to a nonempty component")
   315	                            .as_str();
   316	                        (
   317	                            Some(format!("run-local:{run_key}:{leader}")),
   318	                            if ids.len() > 1 {
   319	                                component_basis
   320	                            } else {
   321	                                IdentityBasis::ProvisionalSingleton
   322	                            },
   323	                        )
   324	                    }
   325	                },
   326	                |number| {
   327	                    (
   328	                        Some(format!("source-reported:companies-house:{number}")),
   329	                        if company(observation).is_some() {
   330	                            IdentityBasis::SourceReportedCompany
   331	                        } else {
   332	                            component_basis
   333	                        },
   334	                    )
   335	                },
   336	            );
   337	            observations.push(ObservationResolution {
   338	                funder_id: observation.funder_id.clone(),
   339	                identity_id,
   340	                identity_basis,
   341	            });
   342	        }
   343	        observations
   344	    }
   345	}
