    72	fn classify(a: &Observation, b: &Observation, probability: f64) -> EdgeEligibility {
    73	    if kind(a) != EntityKind::Unknown && kind(b) != EntityKind::Unknown && kind(a) != kind(b) {
    74	        return EdgeEligibility::Reject(PairReason::PersonOrganisationConflict);
    75	    }
    76	    let exact_name = a.name_normalized.is_some() && a.name_normalized == b.name_normalized;
    77	    let full_addresses = a.address_match_quality == AddressMatchQuality::NumberedStreet
    78	        && b.address_match_quality == AddressMatchQuality::NumberedStreet
    79	        && a.address_normalized.is_some()
    80	        && b.address_normalized.is_some();
    81	    if exact_name
    82	        && full_addresses
    83	        && a.address_normalized == b.address_normalized
    84	        && probability >= AUTOMATIC_THRESHOLD
    85	    {
    86	        EdgeEligibility::Link(LinkEvidence::Statistical)
    87	    } else if exact_name && a.role == FunderRole::Donor && b.role == FunderRole::Donor {
    88	        EdgeEligibility::Link(LinkEvidence::DonorName)
    89	    } else if full_addresses && a.address_normalized != b.address_normalized {
    90	        EdgeEligibility::Reject(PairReason::FullAddressDisagreement)
    91	    } else {
    92	        EdgeEligibility::Review
    93	    }
    94	}
    95	type CandidateEdges = BTreeMap<(FunderObservationId, FunderObservationId), CandidateEdge>;
    96	fn expanded_edges(
    97	    input: &ResolutionInput,
    98	    scoring: &ScoringInput,
    99	    pairs: Vec<ScoredPair>,
   100	) -> Result<CandidateEdges, EntityIngestionError> {
   101	    let mut edges = BTreeMap::new();
   102	    for pair in pairs {
   103	        for left in &scoring.members[&pair.left] {
   104	            for right in &scoring.members[&pair.right] {
   105	                if left == right {
   106	                    continue;
   107	                }
   108	                let (left, right) = if left < right {
   109	                    (left, right)
   110	                } else {
   111	                    (right, left)
   112	                };
   113	                let a = &input.observations[left];
   114	                let b = &input.observations[right];
   115	                if company(a).is_some() && company(b).is_some() {
   116	                    continue;
   117	                }
   118	                edges
   119	                    .entry((left.clone(), right.clone()))
   120	                    .or_insert_with(|| CandidateEdge {
   121	                        eligibility: classify(a, b, pair.probability),
   122	                        decision: PairDecision {
   123	                            left_funder_id: left.clone(),
   124	                            right_funder_id: right.clone(),
   125	                            probability: pair.probability,
   126	                            name_level: pair.name_level,
   127	                            address_level: pair.address_level,
   128	                            disposition: PairDisposition::Review,
   129	                            reason: PairReason::InsufficientExactEvidence,
   130	                        },
   131	                    });
   132	                if edges.len() > scoring.candidate_budget {
   133	                    return Err(invalid(
   134	                        "expanded observation pairs exceed candidate budget; raise candidate_budget explicitly",
   135	                    ));
   136	                }
   137	            }
   138	        }
   139	    }
   140	    Ok(edges)
   141	}
