   146	impl Components {
   147	    fn new(input: &ResolutionInput) -> Self {
   148	        let mut components: Vec<BTreeSet<FunderObservationId>> = Vec::new();
   149	        let mut anchors = BTreeMap::<String, usize>::new();
   150	        let mut group = BTreeMap::new();
   151	        for observation in input.observations.values() {
   152	            let index = if let Some(number) = company(observation) {
   153	                *anchors.entry(number).or_insert_with(|| {
   154	                    components.push(BTreeSet::new());
   155	                    components.len() - 1
   156	                })
   157	            } else {
   158	                components.push(BTreeSet::new());
   159	                components.len() - 1
