   214	                (&edge.left_funder_id, &edge.right_funder_id),
   215	                (&edge.right_funder_id, &edge.left_funder_id),
   216	            ]
   217	            .iter()
   218	            .any(|(unknown, known)| {
   219	                company(&input.observations[*unknown]).is_none()
   220	                    && company(&input.observations[*known]).is_some()
   221	                    && candidate_companies
   222	                        .get(&unanchored.group[*unknown])
   223	                        .is_some_and(|numbers| numbers.len() > 1)
   224	            });
