  7	use serde::Serialize;
  8	use std::collections::{BTreeMap, BTreeSet};
  9	
 10	pub(crate) const POLICY_VERSION: &str = "funder-resolution-v2";
 11	pub(crate) const AUTOMATIC_THRESHOLD: f64 = 0.999;
 12	
 13	mod attribution;
 14	mod identity;
 15	fn invalid(message: impl Into<String>) -> EntityIngestionError {
 16	    EntityIngestionError::DataError(message.into())
 17	}
