 26	/// Evidence basis of an assigned identity, independent of reporting attribution.
 27	#[derive(Clone, Copy, Debug, Serialize)]
 28	#[serde(rename_all = "snake_case")]
 29	pub enum IdentityBasis {
 30	    /// An accepted captured company number, without registry verification.
 31	    SourceReportedCompany,
 32	    /// An accepted exact name and full address score.
 33	    StatisticalLink,
 34	    /// Exact donor names are necessary to connect the identity.
 35	    DonorNameLink,
 36	    /// Statistical and exact donor-name links support the identity.
 37	    StatisticalAndDonorNameLink,
 38	    /// A separate local identity without evidence of a cross-observation match.
 39	    ProvisionalSingleton,
 40	    /// No usable name or eligible captured identifier.
 41	    Unresolved,
 42	}
 43	/// One outcome for each input source-role observation.
 44	#[derive(Serialize)]
 45	pub struct ObservationResolution {
 46	    pub(crate) funder_id: FunderObservationId,
 47	    pub(crate) identity_id: Option<String>,
 48	    pub(crate) identity_basis: IdentityBasis,
 49	}
 50	/// Policy disposition of one statistical candidate edge.
 51	#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
 52	#[serde(rename_all = "snake_case")]
 53	pub enum PairDisposition {
 54	    /// The edge passed its evidence rule and component constraints.
 55	    Accepted,
 56	    /// The edge remains a candidate for human review.
 57	    Review,
 58	    /// Retained evidence contradicts automatic merging.
 59	    Rejected,
 60	}
 61	/// Evidence reason for a candidate disposition.
 62	#[derive(Clone, Copy, Debug, Serialize)]
 63	#[serde(rename_all = "snake_case")]
 64	pub enum PairReason {
 65	    /// The initial exact name and numbered-street rule is not satisfied.
 66	    InsufficientExactEvidence,
 67	    /// Explicit person and organisation kinds disagree.
 68	    PersonOrganisationConflict,
 69	    /// Two usable numbered-street addresses disagree.
 70	    FullAddressDisagreement,
 71	    /// An eligible unanchored group reaches more than one company anchor.
 72	    CompetingCompanyAnchors,
 73	    /// A union would mix company numbers or incompatible entity kinds.
 74	    ComponentIdentityConflict,
 75	    /// Exact names, full addresses, threshold, and component constraints agree.
 76	    ExactNameFullAddressThreshold,
 77	    /// Both donors have the same usable normalized name.
 78	    ExactDonorName,
 79	}
 80	/// A scored edge retained for inspection, including rejected evidence.
 81	#[derive(Serialize)]
 82	pub struct PairDecision {
 83	    pub(crate) left_funder_id: FunderObservationId,
 84	    pub(crate) right_funder_id: FunderObservationId,
 85	    pub(crate) probability: f64,
 86	    pub(crate) name_level: i32,
 87	    pub(crate) address_level: i32,
 88	    pub(crate) disposition: PairDisposition,
 89	    pub(crate) reason: PairReason,
 90	}
 91	/// Source role used for one payment's reporting decision.
 92	#[derive(Clone, Copy, Debug, Serialize)]
 93	#[serde(rename_all = "snake_case")]
 94	pub enum AttributionBasis {
