400	                .find_map(|row| row.donor_company_number.clone());
401	            let kind = if company_number.is_some() {
402	                Some("Company".to_owned())
403	            } else {
404	                group.iter().find_map(|row| row.donor_kind.clone())
405	            };
406	            let names = group
407	                .iter()
408	                .find_map(|row| row.name_raw.as_ref().filter(|name| !name.trim().is_empty()));
409	            let aliases = group
410	                .iter()
411	                .filter_map(|row| row.name_raw.as_ref())
412	                .filter(|name| !name.trim().is_empty())
413	                .cloned()
414	                .collect::<BTreeSet<_>>();
415	            let name = names.cloned().unwrap_or_else(|| {
