+#[derive(Clone, Copy, Debug, PartialEq, Eq)]
+enum EntityKind {
+    Person,
+    Organisation,
+    Unknown,
+}
+fn kind(observation: &Observation) -> EntityKind {
+    match observation
+        .donor_kind
+        .as_deref()
+        .map(str::trim)
+        .map(str::to_ascii_lowercase)
+        .as_deref()
+    {
+        Some("individual" | "person") => EntityKind::Person,
+        Some(
