     8	#[serde(rename_all = "snake_case")]
     9	pub enum NameStatus {
    10	    /// A nonempty name, retained without guessing its entity type.
    11	    Present,
    12	    /// No name or only whitespace.
    13	    Missing,
    14	    /// An explicit confidentiality or anonymity placeholder.
    15	    Withheld,
    16	}
    17	
    18	/// Independent candidate representations, never keys for merging observations.
    19	#[derive(Debug, Serialize)]
    20	pub struct FunderNameFeatures {
    21	    /// Original source spelling, including placeholders and whitespace.
    22	    pub name_raw: Option<String>,
    23	    /// Explicit absence or withholding classification.
    24	    pub name_status: NameStatus,
    25	    /// NFKC, lowercase, and collapsed whitespace.
    26	    pub name_normalized: Option<String>,
    27	    /// Normalized name with decomposed combining marks removed.
    28	    pub name_accent_folded: Option<String>,
    29	    /// Punctuation-normalized tokens in source order.
    30	    pub name_tokens: Option<String>,
    31	    /// Sorted tokens, retaining repeated words.
    32	    pub name_token_key: Option<String>,
    33	    /// Normalized primary name without explicit trading-as text.
    34	    pub primary_name_normalized: Option<String>,
    35	    /// Primary-name tokens without an explicit UK legal suffix.
    36	    pub organisation_core: Option<String>,
    37	    /// Token sequence without common leading honorifics.
    38	    pub person_core: Option<String>,
    39	    /// Initial letters of the person-core tokens.
    40	    pub person_initials: Option<String>,
    41	    /// Organisation-core initials, excluding listed connective words.
    42	    pub organisation_initials: Option<String>,
    43	    /// A source acronym whose letters agree with an explicit parenthetical expansion.
    44	    pub explicit_acronym: Option<String>,
    45	    /// Normalized expansion validated against the explicit acronym.
    46	    pub acronym_expansion_normalized: Option<String>,
    47	    /// Parenthetical contents in their original spelling and order.
    48	    pub parenthetical_text: Vec<String>,
    49	    /// Names following an explicit trading-as marker, without inferred aliases.
    50	    pub explicit_aliases: Vec<String>,
