    SameCompany(CompanyNumber),
    SameName,
    SameOrganisationCore,
    ExplicitAlias,
    ExplicitAcronymExpansion,
    SameTokenSet,
    SameUnionRoot,
    UnionBranchOfRoot,
    SameAddress,
    DifferentAddress,
}
