   181	fn person_core(name: &str) -> String {
   182	    const TITLES: &[&str] = &[
   183	        "mr",
   184	        "mrs",
   185	        "ms",
   186	        "miss",
   187	        "mx",
   188	        "dr",
   189	        "prof",
   190	        "professor",
   191	        "sir",
   192	        "dame",
   193	        "lord",
   194	        "lady",
   195	        "rev",
   196	        "reverend",
   197	        "rt",
   198	        "hon",
   199	    ];
   200	    name.split_whitespace()
   201	        .skip_while(|word| TITLES.contains(word))
   202	        .collect::<Vec<_>>()
   203	        .join(" ")
   204	}
   205	
   206	fn initials(name: &str, omit_connectives: bool) -> String {
   207	    const CONNECTIVES: &[&str] = &["a", "an", "and", "for", "in", "of", "on", "the", "to"];
   208	    name.split_whitespace()
   209	        .filter(|word| !omit_connectives || !CONNECTIVES.contains(word))
   210	        .filter_map(|word| word.chars().next())
   211	        .collect()
   212	}
   213	
   214	fn parentheses(raw: &str) -> (Vec<String>, bool) {
   215	    let mut result = Vec::new();
   216	    let mut depth = 0;
   217	    let mut start = 0;
   218	    let mut unbalanced = false;
   219	    for (index, c) in raw.char_indices() {
   220	        match c {
   221	            '(' => {
   222	                if depth == 0 {
   223	                    start = index + 1;
   224	                }
   225	                depth += 1;
   226	            }
   227	            ')' if depth > 0 => {
   228	                depth -= 1;
   229	                if depth == 0 {
   230	                    result.push(raw[start..index].to_owned());
   231	                }
   232	            }
   233	            ')' => unbalanced = true,
   234	            _ => {}
   235	        }
   236	    }
   237	    if depth > 0 {
   238	        result.push(raw[start..].to_owned());
   239	    }
   240	    (result, unbalanced || depth > 0)
   241	}
   242	
   243	fn explicit_acronym(raw: &str, parenthetical: &[String]) -> Option<(String, String)> {
   244	    let before = raw.split('(').next()?.trim();
   245	    for expansion in parenthetical {
   246	        for (candidate, full) in [(before, expansion.as_str()), (expansion.as_str(), before)] {
   247	            let letters = candidate
   248	                .chars()
   249	                .filter(|c| *c != '.' && !c.is_whitespace())
   250	                .collect::<String>();
   251	            if (2..=10).contains(&letters.chars().count())
   252	                && letters.chars().all(|c| c.is_ascii_uppercase())
   253	                && letters.to_lowercase() == initials(&tokens(&normalize(full)), true)
   254	            {
   255	                return Some((letters.to_lowercase(), normalize(full)));
   256	            }
   257	        }
   258	    }
   259	    None
   260	}
   261	
   262	fn alias_marker(candidate: &str, top_level_only: bool) -> Option<(usize, usize)> {
   263	    let lower = candidate.to_ascii_lowercase();
   264	    let mut found = None;
   265	    for marker in ["trading as", "t/a"] {
   266	        for (index, _) in lower.match_indices(marker) {
   267	            let boundary = (index == 0 || lower[..index].ends_with([' ', '(', ',']))
   268	                && lower[index + marker.len()..].starts_with(char::is_whitespace);
   269	            let depth = candidate[..index].chars().fold(0_i32, |depth, c| match c {
   270	                '(' => depth + 1,
   271	                ')' => depth - 1,
   272	                _ => depth,
   273	            });
   274	            if boundary
   275	                && (!top_level_only || depth == 0)
