576	fn fingerprint_files(
577	    paths: impl IntoIterator<Item = PathBuf>,
578	) -> Result<String, EntityIngestionError> {
579	    let mut paths = paths.into_iter().collect::<Vec<_>>();
580	    paths.sort();
581	    let mut digest = Sha256::new();
582	    for path in paths {
583	        let name = path
584	            .file_name()
585	            .and_then(|name| name.to_str())
586	            .ok_or_else(|| data_error("artifact filename is not UTF-8"))?;
587	        let bytes = fs::read(&path).map_err(read_error)?;
588	        digest.update(u64::try_from(name.len()).unwrap_or(u64::MAX).to_be_bytes());
589	        digest.update(name.as_bytes());
590	        digest.update(u64::try_from(bytes.len()).unwrap_or(u64::MAX).to_be_bytes());
591	        digest.update(bytes);
592	    }
593	    Ok(format!("{:x}", digest.finalize()))
594	}
