                    return vec![DeclarationRecord::new_without_funding_entry(
                        member.member_id().to_string(),
                        member.parliament_member_id(),
                        declaration.id().value(),
                        declaration.parent_id().map(DeclarationId::value),
                        declaration.category_id(),
