                "DELETE FROM exposed.funding_entries WHERE source_declaration_id = $1",
                i32::try_from(declaration.source_declaration_id).map_err(db_error)?
            )
            .execute(&mut *tx)
            .await
            .map_err(db_error)?;
        }
